const item = $input.first().json;
const body = item.body || item;
const name = (body.name || '').trim();
const email = (body.email || '').toLowerCase().trim();
const role = body.role === 'artista' ? 'artista' : 'cliente';
const passwordDemo = body.passwordDemo || '';

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const isValidEmail = email && emailRegex.test(email);
const acceptTerms = Boolean(body.acceptTerms === true || body.acceptTerms === 'true');
const hasBasicFields = Boolean(name && isValidEmail && passwordDemo.length >= 6);
const hasRequired = Boolean(hasBasicFields && acceptTerms);

let validationError = null;
if (!acceptTerms) {
  validationError = 'Debes aceptar las condiciones para crear tu cuenta.';
} else if (!hasBasicFields) {
  validationError = 'Faltan campos obligatorios: se requiere nombre, correo válido y contraseña de al menos 6 caracteres.';
}

return [{
  json: {
    ...body,
    name,
    email,
    role,
    passwordDemo,
    acceptTerms,
    termsAccepted: true,
    termsAcceptedAt: body.termsAcceptedAt || new Date().toISOString(),
    termsVersion: body.termsVersion || '1.0',
    isValid: hasRequired,
    validationError
  }
}];

const payload = $('Validar Payload').item.json;
let users = [];
try {
  users = await this.helpers.httpRequest({
    method: 'GET',
    url: 'http://localhost:3000/users?email=' + encodeURIComponent(payload.email)
  });
} catch (error) {
  users = [];
}

const isDuplicate = Array.isArray(users) && users.length > 0;

return [{
  json: {
    ...payload,
    isDuplicate
  }
}];
